<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;
class StoreRecurringPlanRequest extends FormRequest { public function authorize():bool{return $this->user()?->hasPermission('recurring_plans.edit')??false;} public function rules():array{return ['customer_id'=>['required','integer','exists:customers,id'],'name'=>['required','string','max:150'],'frequency'=>['required','in:daily,weekly,monthly'],'weekdays'=>['nullable','array','required_if:frequency,weekly'],'weekdays.*'=>['integer','between:1,7'],'day_of_month'=>['nullable','integer','between:1,31','required_if:frequency,monthly'],'start_date'=>['required','date'],'end_date'=>['nullable','date','after_or_equal:start_date'],'auto_generate'=>['nullable','boolean'],'delivery_address'=>['nullable','string','max:5000'],'delivery_city'=>['nullable','string','max:100'],'delivery_state'=>['nullable','string','max:100'],'delivery_pincode'=>['nullable','string','max:10'],'notes'=>['nullable','string','max:10000'],'items'=>['required','array','min:1'],'items.*.product_id'=>['nullable','integer','exists:products,id'],'items.*.design_id'=>['nullable','integer'],'items.*.description'=>['required','string','max:1000'],'items.*.quantity'=>['required','numeric','gt:0'],'items.*.unit'=>['required','string','max:30'],'items.*.unit_price'=>['required','numeric','min:0'],'items.*.discount_amount'=>['nullable','numeric','min:0'],'items.*.tax_rate'=>['nullable','numeric','min:0','max:100']];}}
